package com.chromvoid.air.ui.credentials

import com.chromvoid.air.bridge.wire.PassmanagerPasswordGenerateRequest
import com.chromvoid.air.ui.support.FailureKind
import com.chromvoid.air.ui.support.failureKind
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/**
 * A candidate password, generated by Core and held only while the sheet is
 * open. The form owns saving: the candidate reaches the draft when the person
 * uses it, and a changed setting drops the one on screen rather than leaving a
 * password that no longer matches the settings above it.
 */
public class PasswordGeneratorModel(
    private val store: CredentialStore,
    private val generation: ULong,
    private val scope: CoroutineScope,
    private val onUse: (String) -> Unit,
) {
    public enum class Status { READY, GENERATING, REVOKED }

    public enum class Issue { NO_TYPES, INVALID, FAILED, NOTHING_TO_USE, REVOKED }

    public data class Settings(
        val length: Int = DEFAULT_LENGTH,
        val lowercase: Boolean = true,
        val uppercase: Boolean = true,
        val digits: Boolean = true,
        val symbols: Boolean = false,
    ) {
        internal val anyType: Boolean get() = lowercase || uppercase || digits || symbols
    }

    public data class State(
        val settings: Settings = Settings(),
        val status: Status = Status.READY,
        val password: String? = null,
        val revealed: Boolean = false,
        val issue: Issue? = null,
    )

    private val mutableState = MutableStateFlow(State())
    public val state: StateFlow<State> = mutableState.asStateFlow()
    private var work: Job? = null

    /** A changed setting invalidates the candidate: it was made under the old one. */
    public fun change(update: (Settings) -> Settings) {
        val current = mutableState.value
        if (current.status == Status.REVOKED) return
        val settings = update(current.settings).let { it.copy(length = it.length.coerceIn(MIN_LENGTH, MAX_LENGTH)) }
        if (settings == current.settings) return
        work?.cancel()
        mutableState.value = current.copy(
            settings = settings,
            status = Status.READY,
            password = null,
            revealed = false,
            issue = null,
        )
    }

    public fun generate() {
        val current = mutableState.value
        if (current.status != Status.READY) return
        work?.cancel()
        if (!current.settings.anyType) {
            mutableState.value = current.copy(password = null, revealed = false, issue = Issue.NO_TYPES)
            return
        }
        mutableState.value = current.copy(
            status = Status.GENERATING,
            password = null,
            revealed = false,
            issue = null,
        )
        val request = PassmanagerPasswordGenerateRequest(
            digits = current.settings.digits,
            length = current.settings.length.toLong(),
            lowercase = current.settings.lowercase,
            symbols = current.settings.symbols,
            uppercase = current.settings.uppercase,
        )
        work = scope.launch {
            try {
                val password = store.generatePassword(request, generation)
                val after = mutableState.value
                if (after.status != Status.GENERATING) return@launch
                mutableState.value = if (password.isEmpty()) {
                    after.copy(status = Status.READY, issue = Issue.FAILED)
                } else {
                    after.copy(status = Status.READY, password = password)
                }
            } catch (cancellation: CancellationException) {
                throw cancellation
            } catch (error: Exception) {
                val after = mutableState.value
                if (after.status != Status.GENERATING) return@launch
                when (error.failureKind) {
                    FailureKind.REVOKED -> revoke()
                    FailureKind.INVALID_INPUT ->
                        mutableState.value = after.copy(status = Status.READY, issue = Issue.INVALID)
                    else -> mutableState.value = after.copy(status = Status.READY, issue = Issue.FAILED)
                }
            }
        }
    }

    public fun toggleReveal() {
        val current = mutableState.value
        if (current.status != Status.READY || current.password == null) return
        mutableState.value = current.copy(revealed = !current.revealed)
    }

    /** Hands the candidate to the form. Nothing is saved: the form's save does that. */
    public fun use() {
        val current = mutableState.value
        if (current.status != Status.READY) return
        val password = current.password
        if (password == null) {
            mutableState.value = current.copy(issue = Issue.NOTHING_TO_USE)
            return
        }
        onUse(password)
    }

    /** The session ended: the candidate goes with it. */
    public fun revoke() {
        work?.cancel()
        mutableState.value = State(
            settings = mutableState.value.settings,
            status = Status.REVOKED,
            issue = Issue.REVOKED,
        )
    }

    public fun close() {
        work?.cancel()
        mutableState.value = State(status = Status.REVOKED)
    }

    public companion object {
        public const val MIN_LENGTH: Int = 4
        public const val MAX_LENGTH: Int = 128
        public const val DEFAULT_LENGTH: Int = 20
    }
}
